package com.devopsclassroom.entity;
import com.fasterxml.jackson.annotation.JsonIgnore; import jakarta.persistence.*;
@Entity @Table(name="trilhas") public class Trilha { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @Column(nullable=false,length=160) private String titulo; @Column(length=500) private String descricao; @Lob @Column(name="conteudo_json",nullable=false) private String conteudoJson="[]"; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="professor_id") @JsonIgnore private Usuario professor; @Column(nullable=false) private boolean ativa=true; public Long getId(){return id;} public void setId(Long v){id=v;} public String getTitulo(){return titulo;} public void setTitulo(String v){titulo=v;} public String getDescricao(){return descricao;} public void setDescricao(String v){descricao=v;} public String getConteudoJson(){return conteudoJson;} public void setConteudoJson(String v){conteudoJson=v;} public Usuario getProfessor(){return professor;} public void setProfessor(Usuario v){professor=v;} public boolean isAtiva(){return ativa;} public void setAtiva(boolean v){ativa=v;} }
